Your expense tracker is below. Add items with an amount and category, and it keeps a running total, a budget bar and a split by category. Entries stay only while this page is open unless saving is allowed here.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h2{margin:0 0 12px;font-size:18px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{font:inherit;padding:7px 9px;border:1px solid #ccc;border-radius:6px}
input{flex:1;min-width:90px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.big{font-size:24px;font-weight:600}
.bar{height:10px;background:#e3e3e8;border-radius:5px;overflow:hidden;margin-top:6px}
.fill{height:100%;background:#2b6cb0}
.over{background:#c53030}
.cat{display:flex;justify-content:space-between;font-size:14px;margin-top:8px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
.muted{color:#777;font-size:12px}
</style></head><body>
<div class="card">
<h2>Monthly expenses</h2>
<div class="row"><input id="m" type="month"><input id="b" type="number" placeholder="Monthly budget (₹)" value="30000"></div>
<div class="big" id="total">₹0</div>
<div class="muted" id="left"></div>
<div class="bar"><div class="fill" id="fill" style="width:0"></div></div>
</div>
<div class="card">
<div class="row">
<input id="n" placeholder="What for?">
<input id="a" type="number" placeholder="Amount (₹)">
</div>
<div class="row">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option></select>
<input id="d" type="date">
<button id="add">Add</button>
</div>
</div>
<div class="card"><h2>By category</h2><div id="cats"></div></div>
<div class="card"><h2>Entries</h2><div id="list"></div></div>
<script>
var data=[];
try{data=JSON.parse(localStorage.getItem("exp")||"[]")}catch(e){}
var $=function(i){return document.getElementById(i)};
var inr=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
var today=new Date().toISOString().slice(0,10);
$("d").value=today;$("m").value=today.slice(0,7);
function save(){try{localStorage.setItem("exp",JSON.stringify(data))}catch(e){}}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function render(){
var mo=$("m").value;
var rows=data.map(function(e,i){e.i=i;return e}).filter(function(e){return e.d.slice(0,7)===mo});
var tot=rows.reduce(function(s,e){return s+e.a},0);
var bud=parseFloat($("b").value)||0;
$("total").textContent=inr(tot)+" spent";
$("left").textContent=bud?(tot<=bud?inr(bud-tot)+" left of "+inr(bud):inr(tot-bud)+" over budget of "+inr(bud)):"Set a budget to see what is left";
var f=$("fill");f.style.width=bud?Math.min(100,tot/bud*100)+"%":"0";
f.className="fill"+(bud&&tot>bud?" over":"");
var by={};rows.forEach(function(e){by[e.c]=(by[e.c]||0)+e.a});
var h="";Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
var p=tot?by[k]/tot*100:0;
h+='<div class="cat"><span>'+k+'</span><span>'+inr(by[k])+' ('+Math.round(p)+'%)</span></div><div class="bar"><div class="fill" style="width:'+p+'%"></div></div>'});
$("cats").innerHTML=h||'<div class="muted">Nothing yet this month.</div>';
rows.sort(function(x,y){return y.d.localeCompare(x.d)});
$("list").innerHTML=rows.map(function(e){
return '<div class="item"><span>'+esc(e.n)+'<br><span class="muted">'+e.c+' · '+e.d+'</span></span><span>'+inr(e.a)+' <button class="x" data-i="'+e.i+'">✕</button></span></div>'}).join("")||'<div class="muted">No entries.</div>';
}
$("add").onclick=function(){
var a=parseFloat($("a").value);
if(!a||a<=0)return;
data.push({n:$("n").value.trim()||$("c").value,a:a,c:$("c").value,d:$("d").value||today});
$("n").value="";$("a").value="";save();
$("m").value=data[data.length-1].d.slice(0,7);render();
};
$("list").onclick=function(ev){
var i=ev.target.getAttribute("data-i");
if(i!==null){data.splice(+i,1);save();render()}
};
$("m").onchange=render;$("b").oninput=render;
render();
</script>
</body></html>
```

